def calls(source):
    # Bind label/preload operations to the same original owner instance
    source=source.replace('AudioManager.GetMissionAudioLoadedLabel(', 'AudioMission_GetLoadedLabel(&AudioManager, ').replace('AudioManager.PreloadMissionAudio(', 'AudioMission_Preload(&AudioManager, ')
    for name,target in [('GetMissionAudioLoadedLabel','GetLoadedLabel'),('PreloadMissionAudio','Preload')]:source=re.sub(r'(?<![\w.:>])'+name+r'\(', 'AudioMission_'+target+'(this, ',source)
    return source
