def logic(source):
    # Remove the exact former table, failure storage, and three migrated function bodies
    source=source.replace('bool8 g_bMissionAudioLoadFailed[MISSION_AUDIO_SLOTS];\n','').replace(TABLE,'')
    for prefix,name in [('', 'FindMissionAudioSfx'),('cAudioManager::','GetMissionAudioLoadedLabel'),('cAudioManager::','PreloadMissionAudio')]:source=source.replace(function(source,prefix,name)+'\n','')
    return police.logic(playback.logic(calls(source)))
def facade(source):
    # Move both existing public mission-data exports intact into C
    for name in ['GetMissionAudioLoadedLabel','PreloadMissionAudio']:source=source.replace(function(source,'DMAudio_',name)+'\n','')
    return police.facade(calls(source))
def header(source):
    # Keep all owner fields and add only C mission-data declarations
    source='\n'.join(line for line in source.split('\n') if not re.search(r'\b(?:GetMissionAudioLoadedLabel|PreloadMissionAudio)\(',line))
    return police.header(playback.header(source.replace('void AudioManager_InitState(cAudioManager *manager);',PROTOTYPES+'void AudioManager_InitState(cAudioManager *manager);')))
